import { isInteger, isNonEmptyString, isPlainObject, isPositiveNumber } from "@zudojs/types";

function problems(value: unknown): string[] {
  if (!isPlainObject(value)) return ["(not an object)"];
  const failing: string[] = [];
  if (!isNonEmptyString(value.sku)) failing.push("sku");
  if (!isInteger(value.qty) || value.qty < 1 || value.qty > 99) failing.push("qty");
  if (!isInteger(value.unitKobo) || !isPositiveNumber(value.unitKobo)) failing.push("unitKobo");
  return failing;
}

console.log(JSON.stringify(problems({ sku: "RICE-5KG", qty: 2, unitKobo: 650000 })));
console.log(JSON.stringify(problems({ sku: "", qty: 100, unitKobo: 6500.5 })));
console.log(JSON.stringify(problems([1, 2])));

