import type { Brand } from "@zudojs/constants";

type InvoiceId = Brand<string, "InvoiceId">;

function parseInvoiceId(value: unknown): InvoiceId {
  if (typeof value !== "string" || !/^INV-\d{4}-\d{6}$/.test(value)) {
    throw new Error(`Not an invoice id: ${JSON.stringify(value)}`);
  }
  return value as InvoiceId;
}

for (const raw of ["INV-2026-000123", "INV-26-123", "inv-2026-000123", 123]) {
  try {
    console.log("ok", parseInvoiceId(raw));
  } catch (error) {
    console.log((error as Error).message);
  }
}

