import { Limits } from "@zudojs/constants";
import { toBoolean, toNumber } from "@zudojs/types";

function readListQuery(search: string) {
  const query = new URLSearchParams(search);
  return {
    page: toNumber(query.get("page"), 1),
    pageSize: Math.min(toNumber(query.get("pageSize"), 20), Limits.MAX_PAGE_SIZE),
    inStock: toBoolean(query.get("inStock"), false),
  };
}

console.log(JSON.stringify(readListQuery("page=2&pageSize=&inStock=yes")));
console.log(JSON.stringify(readListQuery("pageSize=5000&inStock=maybe")));

