import { TimeMs } from "@zudojs/constants";
import { FixedClock } from "@zudojs/types";
import type { Clock } from "@zudojs/types";

function createOtpService(clock: Clock) {
  return {
    issue: () => clock.now(),
    isValid: (issuedAt: number) => clock.now() - issuedAt < 5 * TimeMs.MINUTE,
  };
}

const clock = new FixedClock(Date.UTC(2026, 8, 24, 9));
const otp = createOtpService(clock);
const issuedAt = otp.issue();
for (const step of [0, 4, 1]) {
  clock.advance(step * TimeMs.MINUTE);
  console.log((clock.now() - issuedAt) / TimeMs.MINUTE, "min:", otp.isValid(issuedAt));
}

