import { HttpStatus, isClientError, isRedirectStatus, isServerError, isSuccessStatus } from "@zudojs/constants";

function describeStatus(code: number): string {
  if (code === HttpStatus.TOO_MANY_REQUESTS || code === HttpStatus.SERVICE_UNAVAILABLE) return "retry later";
  if (isSuccessStatus(code)) return "ok";
  if (isRedirectStatus(code)) return "redirect";
  if (isClientError(code)) return "fix the request";
  if (isServerError(code)) return "server problem";
  return "unknown";
}

console.log([201, 301, 404, 429, 500, 503].map(describeStatus).join(" | "));

