import { TimeMs } from "@zudojs/constants";
import type { Clock } from "@zudojs/types";

// A clock that moves 1 ms every time it is read, like a real one under load.
let t = Date.UTC(2026, 8, 24, 9);
const tickingClock: Clock = { now: () => t++ };

function place(clock: Clock) {
  const now = clock.now();
  return { createdAt: now, payBy: now + 30 * TimeMs.MINUTE };
}

const order = place(tickingClock);
console.log(order.payBy - order.createdAt);
